return ['domain'=>'page-builder-sandwich','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'so_SO','project-id-version'=>'page-builder-sandwich','pot-creation-date'=>'2026-09-26T16:59:17+00:00','po-revision-date'=>'2026-09-26T16:59:17+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Page Builder Sandwich'=>'Page Builder Sandwich','https://zinndigital.com/wordpress-plugins/page-builder-sandwich'=>'https://zinndigital.com/wordpress-plugins/page-builder-sandwich','The foundation release of the rebuilt Page Builder Sandwich: a settings and About screen, a footprint-free front-end output layer, and one sample content block.'=>'Soo-saaridii aasaaska ahayd ee Page Builder Sandwich oo la dib u dhisay: shaashadda dejinta iyo Ku saabsan, lakabka wax soo saarka hore ee Footprint-Free ah, iyo hal baloog oo tusaale ah.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'Bixiyeyaasha AI','The makers of ChatGPT. A good all-rounder.'=>'Sameeyeyaasha ChatGPT. Qalab guud oo wanaagsan.','The makers of Claude. Strong at writing and careful reasoning.'=>'Abuurayaasha Claude. Ku xooggan qorista iyo sababaynta taxaddarka leh.','Google\'s Gemini models. Fast and inexpensive.'=>'Moodeellada Gemini ee Google. Waa kuwo dhakhso badan oo jaban.','A European AI company with fast, inexpensive models.'=>'Shirkad AI oo Yurub ah oo leh moodallo degdeg ah, jaban.','Low-cost models that are good at writing and code.'=>'Qaabab jaban oo ku fiican qorista iyo koodhka.','One key for models from many different providers.'=>'Hal fure oo loogu talagalay moodooyinka bixiyeyaal badan oo kala duwan.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Adeeg kasta oo u shaqeeya sida OpenAI\'s API, oo ay ku jirto qaab ay ku shaqeyneyso kombiyuutarkaaga ama adeegahaaga.','General (used when nothing more specific is set)'=>'Guud ahaan (la isticmaalo marka aan wax gaar ah la cayimin)','Writing and rewriting'=>'Qorid iyo dib-u-qorid','Translation'=>'Turjumaad','Code and CSS'=>'Code iyo CSS','Sorry, you are not allowed to access this page.'=>'Waan ka xumahay, looguma oggola inaad gasho boggan.','These settings are shared by every plugin that uses them: %s.'=>'Dejinnitan waxaa wadaaga dhammaan furayaasha adeegsada: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Furayaashaaga waxaa lagu kaydiyaa xog-ururinta boggan waxaana loo diraa oo keliya bixiyaha aad dooratay — weligood annogu nama soo gaaraan.','Step 1 of 2: choose an AI provider'=>'Tallaabada 1 ee 2: dooro bixiye AI ah','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Waxaad keenaysaa furahaaga gaarka ah, markaa waxaad si toos ah uga bixisaa bixiyaha wixii aad isticmaasho. Ma hubtid? Mid kasta oo ka mid ah kuwan ayaa si fiican u shaqeeya; waxaad ku dari kartaa kuwo kale markii dambe.','Next'=>'Kan xiga','Step 2 of 2: connect %s'=>'Tallaabada 2 ee 2: ku xidh %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Geli cinwaanka adeeggaaga OpenAI-waafaqsan, oo ku dhammaada /v1. Furaha waxa la rabaa oo keliya haddii adeeggu uu mid codsado.','Open %s and sign in (or create a free account).'=>'Fur %s oo lagalay (ama abuur akoon bilaash ah).','the %s API keys page'=>'bogga furayaasha API ee %s','Create a new key and copy it.'=>'Abuur fure cusub oona koobiyo.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Halkan ku dheji oo riix "Keydi oo tijaabi". Waxaan dirноq codsi aad u yar si aan u hubino inuu shaqeynayo.','Most providers need a little credit on the account before a key works: %s.'=>'Int aksiiro ah ayaa inta badan u baahan xoogaa deyn ah oo ku jirta akoonka ka hor inta uusan fure shaqayn: %s.','add credit'=>'kordhi lacagta','← Choose a different provider'=>'← Dooq bixiye kale','Address'=>'Cinwaanka','Saved key ends in …%s — paste a new one to replace it'=>'Furaha la kaydiyay wuxuu ku dhammaanayaa …%s — dhejiso mid cusub si aad u bedesho','Key (optional)'=>'Furaha (ikhtiyaari)','API key'=>'Furaha API','Save and test'=>'Keydi oo tamiiti','Providers'=>'Bixiyeyaasha','Provider'=>'Bixiyaha','Status'=>'Xaaladda','Key'=>'Furaha','Get a key'=>'Hel furaha','Test'=>'Tijaabi','Remove'=>'Ka tirtir','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Nooca cusub ee qalab-kordhinta ayaa keydiyay: cusboonaysii qalab-kordhintakan, ama mar labaad gelifuraha.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Furaha la keydiyay hadda lama furi karo (furayaasha amniga ee boggu waa is beddeleen). Geli mar kale.','Not connected'=>'Lama xiriirin','Connected — last test passed %s'=>'Ku xiran — imtixaankii ugu dambeeyay wuu guuleystay %s','Last test failed: %s'=>'Imtixaankii ugu dambeeyay wuu fashilmay: %s','Connected — not tested yet'=>'Ku xidhan — wali lama tijaabin','Which model to use'=>'Waa maxay moodeelka la isticmaalayo','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ waxay calaamad u tahay taladayada hawshaas. Liisku waxa uu ka kooban yahay moodel kasta oo ay furahaagu isticmaali karo, oo si toos ah looga akhriyay adeeg-bixiyaha.','— Recommended for the provider —'=>'— Waxaa lagula talinayaa bixiyaha —','Save models'=>'Keydso moodellada','Refresh the model lists from the providers'=>'Ka cusboonaysii liiska noocyada bixiyeyaasha','best quality'=>'tayada ugu fiican','lowest cost'=>'qiimaha ugu hooseeya','fastest'=>'ugu dhaqso badan','Add a model yourself'=>'Sidaada ugu dar moodel','A model came out today? Paste its exact name to use it straight away.'=>'Maanta ma nooc cusub soo baxay? Geli magaciisa saxda ah si aad si toos ah u isticmaasho.','Model name'=>'Magaca moodelka','Add model'=>'Ku dar qaabka','Recommended models list'=>'Liiska moodellada lagu taliyay','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Liiska moodallada lagu taliyay lama xaqiijin karo, markaa wax talo ah lama soo bandhigayo. Dib u rakib furaha (plugin-ka), ama shid casriyeynta maalinlaha ah ee hoose.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Liistada la isticmaalayo waxaa la daabacay %s. Cusboonaysiin kasta oo plugin ah waxay keentaa mid cusub.','Also check Zinn Digital® once a day for an updated list.'=>'Sidoo kale hubi Zinn Digital® hal mar maalintii si aad u hesho liis la cusboonaysiiyay.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Kaliya codsi soo dejin oo fudud ayaa la dirayaa: ma jiro furaha, ciwaanka goobta, wax ku saabsan nuxurkaaga. Liiska waa la saxiixay, liiska ku guuldareysta hubinta saxiixa waa la iska indhatirayaa.','Last checked %1$s: %2$s.'=>'Markii ugu dambeysay ee la hubiyay %1$s: %2$s.','Save, and check now if turned on'=>'Keydi, oo hadda hubi haddii la shiday','a newer list was installed'=>'liis cusub ayaa la rakibay','already up to date'=>'horay ayuu u cusboonaaday','the download failed the signature check and was ignored'=>'soo dejintu waxay ku guuldareysatay hubinta saxiixa waxaana la iska indhatiray','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® lama gaari karo; liiska hadda jira waa la isticmaalayaa','turned off'=>'damchay','Open'=>'Furo','Check their status page'=>'Hubi boggoodooda xaaladda','Open your billing page'=>'Fur boggaaga biilasha','Open your API keys page'=>'Fur bogtaada furayaasha API-ga','Open the AI settings'=>'Furo goobaha AI-ga','Sorry, you are not allowed to do that.'=>'Waan ka xumahay, looma oggola inaad taas sameyso.','Unknown provider.'=>'Bixiye aan la aqoon.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Geli ciwaanka adeeggaaga, tusaale ahaan http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'Taasi uma eka furaha API. Nuqul ka yeeg mar kale, adiga oo aan wadata meelo bannaan.','Paste your API key first.'=>'Horta geli furahaaga API.','Key removed.'=>'Furaha waa la saaray.','Models saved.'=>'Qaababka waa la keydiyay.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Geli magaca sax ah ee moodeelka, tusaale ahaan sida dukumentiyada bixiyaha ay u qoraan.','Added %s. Choose it under "Which model to use".'=>'La daray %s. Ka dooro hoosta "Nooca la isticmaalayo".','Model removed.'=>'Qaabka la saaray.','Daily updates are off. The list that came with the plugin is used.'=>'Cusboonaysiinada maalinlaha ah waa damtisay. Liiska la socday qalabka dheeriga ah ayaa la isticmaalayaa.','Checked: %s.'=>'La hubiyay: %s.','Model lists refreshed.'=>'Liisaska moodalka waa la cusboonaysiiyay.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Furehaydaada AI waxaa kaydiyay nooc ka cusub mid ka mid ah fiilooyinkaaga. Cusboonaysii fiiladan, ama geli furaha mar labaad oo ah goobaha AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Fureyaga AI ee la kaydiyay lama furan karo mar dambe (furayaasha amniga ee boggu waa is beddeleen). Geli mar labaad goobaha AI.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI lama dejinin weligiis. Ku dar furaha bixiyaha AI dejinta AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Hawushan lama dooran wax nooc ah. Dooro mid ka mid ah dejinta AI.','That AI provider is not supported by this version of the plugin.'=>'Bixiyaha AI-gaas laguma taageero noocaan ah ee qalab-kordhinta.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Boggan ma gaari karo adeeggaaga AI. Hubi inuu shaqaynayo iyo in ciwaankiisa laga soo gaari karo server-kaaga shabakadda (adeeg ka dhex jira kombuyuutarkaaga lagama soo gaari karo bog la martigeliyay).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Boggani ma gaari karo %s. Hubi boggooda xaaladda; haddii ay shaqeynayaan, waxaa laga yaabaa in martigeliyahaagu uu xirayo xiriirada ka baxaya, ama ciwaanku waa khalad.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s waxa uu sheegayaa in koontadaadu ay ka dhammaatay credit ama quota. Ku dar credit ama kor u qaad xadkaaga koontadaada iyaga, kadibna mar kale isku day.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s ma aqbalin furahaaga. Waxaa laga yaabaa in si khaldan loo qoray, la baabi\'iyay ama uu dhacay. Samee fure cusub oo halkan ku dhaji.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s wuxuu diiday codsigan furahaaga. Furaha waxaa laga yaabaa inuusan marin u helin qaabkan ama muuqaalkan, ama akoonkaaga ayaa u baahan in la xaqiijiyo.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Qaabka "%1$s" waxaa laga helin %2$s furehaaga. Dooro qaab kale oo ka tirsan dejinta AI.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Qorshahaaga %2$s kuma jiro tusaalaha "%1$s". Dooro tusaale kale oo ku jira dejinta AI, ama ku cusboonaysii qorshahaaga iyaga.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s waxay xaddidaysaa inta ay xawaarahaagu key-gaaga ku soo diri karto codsiyada. Sug hal daqiiqo oo mar kale isku day, ama kor u qaad xadkaaga sicirka iyaga.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s wax dhibaato ah ayaa haysata hadda (cillad ama culays xad-dhaaf ah dhankooda ah). Dejintaada wax khalad ah kama jiraan. Mar kale isku day dhawaan.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Codsiga AI wuu fashilmay sabab aanan garan karin. Isku day mar kale; haddii ay sii dhacdo, la xiriir taageerada oo u dir macluumaadka hoose.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Bixiyaha AI wuxuu ku jawaabay qaab uusan ku shaqeyn karin ama uusan akhrin karin furahan (plugin). Mar kale isku day; haddii ay dhacdo mar walba, dooro nooc kale ama la xiriir taageerada.','Custom (OpenAI-compatible)'=>'Custom (OpenAI-compatible)','Save a key for this provider first.'=>'Markabkan furaha u keydi bixiyahakan marka hore.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Furahaagu wuu shaqeynayaa, laakiin bixiyaha ma liis gareynayo nooc qoraal ah (text model) oo loogu talagalay. Ku dar nooc adiga laftaadu hoos ku qoran.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Ku xidhan. %1$s waxa uu ku jawaabay adigoo isticmaalaya %2$s. Astaamahaaga AI waa diyaar in la isticmaalo.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Dooxada isticmaalahaagu uma oggola in ay ka faa\'iidaysato AI boggan. Weydii maamule.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Webkaan wuxuu gaadhay xadka uu bishii ku bixin lahaa kharashka AI-ga. Maamulaha ayaa kor u qaadi kara habaynta AI-ga.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Boggan wuxuu gaadhay xadka uu bishii isticmaali jiray ee codsiyada AI. Maamulaha ayaa kordhin kara goobaha AI.','Usage and cost'=>'Isticmaalka iyo kharashka','The log, limits and role permissions apply to AI used through: %s.'=>'Diiwaanka, xadka iyo ogolaanshaha doorka waxaa lagu dabaqaa sirdoonka macmalka (AI) ee lagu isticmaalo iyada oo loo marayo: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Kharashyada waa kuwo qiyaas ah, oo laga soo saaray qiimayaasha la daabacay; qaab aan la aqoon qiimihiisa waxaa loo tiriyaa eber.','This month: %1$s requests, about %2$s.'=>'Bishan: %1$s codsiyo, ku dhawaad %2$s.','When'=>'Goorma','Who'=>'Yaa','Used for'=>'Loo isticmaalay','Model'=>'Qaabka','Tokens in / out'=>'Calaamadaha gudaha / dibadda','About'=>'Ku saabsan','Result'=>'Natiijo','No AI requests have been made yet.'=>'Weli lama samayn codsiyo AI ah.','Done'=>'La dhammeeyey','Limits and permissions'=>'Xadka iyo oggolaanshaha','Monthly spending limit (US dollars)'=>'Xadka kharashka bisha (US dollars)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'U dhaaf madhan xadka la\'aan. AI waxay istaagaysaa inta ka dhiman bisha marka qiimaha qiyaasaha ahi uu gaaro.','Monthly request limit'=>'Xadka codsiga bishii','Leave empty for no limit.'=>'U dhaaf bannaan xad la\'aan.','Who may use AI'=>'Yaa isticmaali kara AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Calaamadi midna si aadl u oggolaato qof kasta oo isticmaali kara sifooyinka plugin-ka inuu isticmaalo AI. Maamulayaashu waxay isticmaali karaan mar walba.','Save limits and permissions'=>'Kaydi xaddidyada iyo fasaxyada','Limits and permissions saved.'=>'Xadka iyo oggolaanshaha waa la keydiyay.','Security error, please refresh the page and try again.'=>'Khalad xagga amniga ah, fadlan dib u cusboonaysii bogga oona isku day mar kale.','Missing newsletter settings. Please contact the admin.'=>'Warka wargelinlaha waa maqan yahay. Fadlan la xiriir maamulaha.','Invalid newsletter settings. Please contact the admin.'=>'Dejinta wargeyska waa mid aan sax ahayn. Fadlan la xiriir maamulaha.','Invalid email address.'=>'Ciwaanka email-ka waa mid aan ansaxeyn.','Too many attempts. Please try again in a few minutes.'=>'Isku dayo aad u badan. Fadlan isku day mar kale daqiiqado kooban kadib.','Something went wrong. Please contact the admin.'=>'Wax qalad ah ayaa dhacay. Fadlan la xiriir maamulaha.','Map'=>'Khariirad','Background video'=>'Muuqaalka asalka ah','%1$s: %2$d font files stored, stylesheet %3$s'=>'%1$s: %2$d faylalka farta la keydiyey, xaashida qaab-dhismeedka %3$s','That family is not stored.'=>'Qoyskaasi lama kaydiyo.','Removed.'=>'Waa la saaray.','That is not a valid font family name.'=>'Taasi ma aha magac qoys far sax ah.','Google Fonts did not return that family. Check the name and try again.'=>'Google Fonts ma soo celinin qoyskaas. Hubi magaca oo dib u day.','The font files could not be downloaded or saved. Check that the uploads folder is writable.'=>'Faylasha farta lama soo dejisan karo ama lama keydin karo. Hubi in galka soo-gelinta la qori karo.','The font stylesheet could not be saved. Check that the uploads folder is writable.'=>'Qoraalka farta ee stylesheet-ka lama keydin karin. Hubi in galka soo-gelinta la qori karo.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Qoraallada shaashadda maamulaha ayaa ka maqan nuqulkan barnaamijka dheeriga ah (plugin). Dib uga rakib xirmo la sii daayay.','This screen needs JavaScript.'=>'Shaarkani wuxuu u baahan yahay JavaScript.','Languages'=>'Luuqadaha','Upgrade'=>'Cusbooneysii','Pricing'=>'Qiimaha','Start Trial'=>'Bilow Imtixaanka','Account'=>'Koontada','Contact Us'=>'Nala Xiriir','Affiliation'=>'Xiriirinta','the kind of softwarePlugin'=>'Kudaraha','greetingHey %s,'=>'Hey %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Ku biir si aad u hesho ogeysiisyo iimayl oo ku saabsan cusboonaysiinta amniga iyo astaamaha, waxyaabo waxbarasho, iyo dalabyo mararka qaar, oo aad la wadaagto macluumaad guud oo ku saabsan deegaanka WordPress. Tani waxay naga caawinaysaa inaan %s ka dhigno mid si fiican ula jaanqaada bogaaga oo si wanaagsan u qabta waxa aad u baahan tahay.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Ku biir si aad u hesho ogeysiisyo iimayl oo ku saabsan cusboonaysiinta amniga iyo astaamaha, waxyaabo waxbarasho, iyo dalabyo mararka qaar, oo aad la wadaagto macluumaad guud oo ku saabsan deegaanka WordPress.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Haddii aad ka boodho arrintan, waa caadi! %1$s weli si fiican ayuu u shaqayn doonaa.','Allow & Continue'=>'Oggolow & Sii wad','verbSkip'=>'Ka bood','Skipping, please wait'=>'Waa la gudbayaa, fadlan sug','Continue'=>'Sii wad','Please wait'=>'Fadlan sug','as activating pluginActivating'=>'Waa la howlgeliyaa','This will allow %s to'=>'Tani waxay u oggolaan doontaa %s inuu','Privacy Policy'=>'Politikada Qarsoodiga','Terms of Service'=>'Shuruudaha Adeegga','License Agreement'=>'Heshiiska Shatiga','Have a license key?'=>'Ma haysataa furaha shatiga?','Activate License'=>'Dhaqaaji Shatiga','View Basic Profile Info'=>'Eeg Macluumaadka Kooban ee Profile-ka','Your WordPress user\'s: first & last name, and email address'=>'Isticmaalahaaga WordPress: magaca koowaad &ka dambe, iyo ciwaanka iimaylka','View Basic Website Info'=>'Arag macluumaadka guud ee mareegta','Homepage URL & title, WP & PHP versions, and site language'=>'URL-ka bogga hoose & cinwaanka, noocyada WP & PHP, iyo luqadda bogga','View Basic %s Info'=>'Arag macluumaadka guud ee %s','Current %s & SDK versions, and if active or uninstalled'=>'SDK-yada %s ee hadda & noocyada, iyo haddii ay shaqeynayaan ama la uninstall-gareeyay','Newsletter'=>'Wargeyska xilliyeedka','Updates, announcements, marketing, no spam'=>'Cusbooneysiin, ogeysiis, suuq-geyn, spam ma jiro','View Diagnostic Info'=>'Eeg Xogta Cilmi-baarista','WordPress & PHP versions, site language & title'=>'Noocyada WordPress & PHP, luqadda iyo cinwaanka bogga','View Plugins & Themes List'=>'Eeg Liiska Hajtisyada & Mawduucyada','Names, slugs, versions, and if active or not'=>'Magacyada, gaabisyada, noocyada, iyo haddii ay shaqeynayaan iyo inkale','optional'=>'ikhtiyaari ah','Never miss an important update'=>'Abid walba oo muhiim ah ha seegin','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Waxaan soo bandhignay ikhtiyaarkan si aadan weligood u seegin warbixin muhiim ah oo aad nooga caawiso inaan ka dhigno %s mid si fiican ula jaanqaadaysa boggaaga oo si wanaagsan u qabaneysa waxaad uga baahan tahay.','Thank you for updating to %1$s v%2$s!'=>'Waad ku mahadsan tahay inaad u cusboonaysiisay %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Horgalku waa inay noqotaa 1 ilaa 8 xaraf oo yar ama nambaro ah, ku billowda xaraf, mana aha inay magac ka dhigto bulginka.','You are not allowed to edit this item.'=>'Looma oggola inaad wax ka beddesho shaygan.','You are not allowed to do this.'=>'Tan ma aha mid la ogol yahay inaad samayso.','Safe mode was turned off because it no longer matches your login. Reload the page.'=>'Qaabka ammaanada waa la damiyay maxaa yeelay mar dambe ma waafaqsana gelitaankaaga. Dib u soo deji bogga.','Only an administrator can use safe mode.'=>'Waxa habka nabdoon isticmaali kara oo keliya maamule.','Safe mode needs a normal browser login.'=>'Habka badbaadada leh wuxuu u baahan yahay galitaanka biraawsarka caadiga ah.','Safe mode could not be set up.'=>'Habka badbaadada lama dejin karo.','Safe mode needs write access to the wp-content/mu-plugins folder.'=>'Habka badbaadada wuxuu u baahan yahay ogolaansho qoraal ah oo loo helo galka wp-content/mu-plugins.','Safe mode could not write to the wp-content/mu-plugins folder.'=>'Habka badbaadada ayaa ku guuldareystay inuu wax ku qoro galka wp-content/mu-plugins.','Sandwich Studio'=>'Sandwich Studio','That page does not exist, or it has been deleted.'=>'Boggaasi ma jiro, ama waa la tirtiray.','Sorry, you are not allowed to edit this item in Sandwich Studio.'=>'Waan ka xumahay, looguma oggola inaad wax ka beddesho shaygan Sandwich Studio.','Sandwich Studio is not built. Reinstall the plugin.'=>'Sandwich Studio lama dhisin. Dib u rakib furaha (plugin).','Add title'=>'Ku dar cinwaan','Type / to choose a block'=>'Geli / si aad u doorato baloog','Loading Sandwich Studio…'=>'Loading Sandwich Studio waa la soo dejinayaa…','Sandwich Studio needs JavaScript. Use the normal editor instead.'=>'Sandwich Studio waxay u baahan tahay JavaScript. Isticmaal tifaftiraha caadiga ah beddelkeeda.','Edit “%s” with Sandwich Studio'=>'Ka beddel “%s” adigoo wata Sandwich Studio','Edit with Sandwich Studio'=>'Ku tiri Sandwich Studio','Blank canvas'=>'Shiraarka madhan','A migration step is running right now. Try again in a minute.'=>'Tallaabo socdaalka ah ayaa hadda socota. Fadlan mar kale isku day daqiiqad dib.','Thank you for subscribing!'=>'Waad ku mahadsan tahay isdiiwaangelinta!','Something went wrong. Please contact the administrator.'=>'Wax bay qalad tay. Fadlan la xiriir maamulaha.','Years'=>'Sanado','Months'=>'Bilaha','Weeks'=>'Toddobaadyada','Days'=>'Maalmaha','Hours'=>'Saacadaha','Minutes'=>'Daqiiqado','Seconds'=>'Ilbiriqsiyo','Go to slide %d'=>'Tag amaahda %d','You\'re already subscribed to our newsletter'=>'Horay ayaad ugu diiwaangashatay warsidahayaga','Email address is already subscribed.'=>'Ciwaanka iimaylka waa mid hore loo diiwaangeliyay.','MailPoet plugin not found. Please contact the admin.'=>'Plugin-ka MailPoet lama helin. Fadlan la xiriir maamulaha.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Waxaa dhisay Neil Lock, oo ah madaxa fulinta ee Zinn Digital® Ltd','Version %s'=>'Nooca %s','Page Builder Sandwich website'=>'Mareegta Page Builder Sandwich','Zinn Digital® website'=>'Mareegta Zinn Digital®','Settings saved.'=>'Dejinta waa la keydiyay.','See the Pro plans and pricing'=>'Eeg qorshayaasha Pro iyo qiimahooda','Front-end output'=>'Soosaarka hore','Class name prefix'=>'Horgalaha magaca fasalka','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Magac kasta oo fasalka ah ee uu turjumaaddu ku daabaco bogaggaaga wuxuu ka bilaabmayaa horgalahan, si uusan bogaggu u muujin kan dhisay. 1 ilaa 8 xaraf oo yar ama nambarro ah, oo ka bilaabmaya xaraf.','Save'=>'Keydi','Beta updates'=>'Cusbooneysiinaha Beta','This site receives beta versions as updates.'=>'Boggan wuxuu helayaa noocyada beta cusbooneysiin ahaan.','This site receives stable versions only.'=>'Boggan wuxuu helayaa noocyada xasiloon kaliya.','Change this on the Account page'=>'Tan kaga beddel bogga Koontada','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Noocyada Beta waxaa la siiyaa rakibaadaha Pro ee ruqseysan ee ku xiran akoonkooda. Marka la xiro, waxaad ka soo biiri kartaa bogga Akoonka.','The request converting this post stopped before it finished, so the post was skipped. Open it to convert it, or convert it again from here.'=>'Codsiga lagu beddelayo qoraalkan ayaa istaagay intii uusan dhammaan, markaa qoraalkii waa la booday. Fur si aad u beddesho, ama mar labaad uga beddel halkan.','There is no backup of this post to restore.'=>'Ma jiro wax kayd ah oo qoraalkan ah oo la soo celiyo.','The converted content could not be saved.'=>'Waxka la beddelay lama keydin karo.','Unknown error.'=>'Khalad aan la aqoon.','No legacy content has been checked yet.'=>'Weli lama hubin wax nuxur ah oo hore.','Restoring legacy content: %1$d of %2$d posts.'=>'So celinta waxyaabihii hore: %1$d ee %2$d qoraal.','Converting legacy content: %1$d of %2$d posts.'=>'Beddelidda nuxurkii hore: %1$d oo ka mid ah %2$d qoraallo.','Undo finished: %1$d restored, %2$d failed.'=>'Dib-u-dejintii waa dhammaatay: %1$d waa la soo celiyay, %2$d waa ay fashilmeen.','Conversion finished: %1$d converted, %2$d unchanged, %3$d failed.'=>'Beddelidii waa dhammaatay: %1$d waa la beddelay, %2$d waa sidoodii, %3$d waa ay fashilmeen.','Legacy content'=>'Qoraalka hore','Pages made with earlier versions of Page Builder Sandwich are converted to blocks in the background. Every post is backed up first, so each conversion can be undone.'=>'Bogagga lagu sameeyay noocyadii hore ee Page Builder Sandwich waxaa loo beddelaa baloogag gadaasha dambe. Qoraal kasta waa la kaydiyaa marka hore, si beddelka kasta loo tirtiro karo.','%d post still holds legacy content.'=>'%d qoraal ayaa weli haya nuxurkii hore.' . "\0" . '%d qoraal ayaa weli xambaarsan waxyaabaha duugga ah.','%d post has a backup.'=>'%d qoraal waxay leedahay keyd.' . "\0" . '%d qoraal waxay leeyihiin keyd.','%d post could not be handled'=>'%d qoraal lama xakamayn karo' . "\0" . '%d qoraallo lama maamuli karin','Post %d'=>'Qoraalka %d','Conversion started. It continues in the background; you can leave this page.'=>'Beddeliddu waa bilowday. Waxay ka socotaa gadaasha; waad ka bixi kartaa boggan.','Convert legacy content'=>'Beddel waxyaabaha duugga ah','Restore every converted post to its legacy content? Changes made to those posts since they were converted will be lost.'=>'Ma rabtaa inaad u soo celiso dhammaan qoraalladii la beddelay qaabkoodii hore? Isbeddellada lagu sameeyay qoraalladaas wixii ka dambeeyay markii la beddelay waa la lixin doonaa.','Undo started. It continues in the background; you can leave this page.'=>'Dib u celinta waa billowday. Waxay ka socotaa gadaal; waad ka bixi kartaa boggan.','Undo all conversions'=>'Gadaal u celi dhammaan beddelallada','Shortcode tag'=>'Astaamaha gaaban','Use letters, numbers, dashes and underscores only.'=>'Isticmaal xarfaha, nambarada, xariijimaha iyo hoosta ka xarriiqaha kaliya.','Attribute name'=>'Magaca sifada','Add attribute'=>'Ku dar sifada','Content'=>'Muxuu ku jiraa','Shortcode'=>'Shortcode','Choose a shortcode tag in the block settings.'=>'Ka dooro calaamadda gaaban goobaha baloogga.','The "%s" control from the old editor is not available in the block editor. Enter the value as text.'=>'Kontoroolka "%s" ee tifaftiraha hore looga heli maayo tifaftiraha baloogga. Geli qiimaha sidoo kale qoraal ahaan.','Choose image'=>'Dooro sawirka','Choose file'=>'Xulo faylka','— Default —'=>'— Caadi ah —','Advanced styling'=>'Qaabeynta horumarsan','Inline CSS'=>'CSS-ka gudaha ah','CSS declarations, for example: min-height: 380px; background-color: #333'=>'Go\'aannada CSS, tusaale ahaan: min-height: 380px; background-color: #333','Effects (legacy classes)'=>'Saamaynta (noocyadii hore)','Space-separated effect names carried over from older versions, for example: hover-shadow'=>'Magacyada saamaynta ee bannaan-u-kala-baxsan ee laga soo qaaday noocyadii hore, tusaale ahaan: hover-shadow','Row'=>'Saf','Width'=>'Ballaca','Content width'=>'Ballaca nuxurka','Full width'=>'Ballac buuxa','Full width, content kept in the middle'=>'Ballac buuxa, nuxurka waxaa lagu hayaa dhexda','Link'=>'Isku xir','Link address'=>'Cinwaanka xiriirinta','Open in a new tab'=>'Ka fur tab cusub','Link relationship'=>'Xiriirka xiriirinta','Alignment'=>'Isku-dabarridda','None'=>'Midna','Left'=>'Bidix','Centre'=>'Xarunta','Right'=>'Midig','Button text'=>'Badhanka qoraalka','Add text…'=>'Ku dar qoraal…','Icon'=>'Icon','SVG markup'=>'Qoraalka SVG','Scripts, links and external references are removed before the icon is shown.'=>'Qoraallada, xiriiriyeyaasha iyo tixraacyada dibadda waa la tirtiraa intaan astaanta la soo bandhigin.','Accessible label'=>'Summaddu la heli karo','Leave empty for a decorative icon.'=>'Astaamaha qurxinta uga tag eber.','Paste SVG markup in the block settings.'=>'Ku dhaji astaanta SVG goobaha baloogga.','New setting name'=>'Magaca dejinta cusub','For example: title or text'=>'Tusaale ahaan: cinwaan ama qoraal','Add setting'=>'Ku dar habeyn','Widget'=>'Widget','Choose a widget'=>'Xulo qalab yar','Widget area'=>'Goobta widget-ka','Choose a widget area'=>'Dooro aagagga farmaajada','This image has no width and height, so the page will jump when it loads. Choose it from the Media Library, or set its width and height.'=>'Sawirkan ma laha ballac iyo dherer, sidaas darteed boggu wuu boodi doonaa marka uu soo hogo. Sii ka dooro Maktabadda Warbaahinta (Media Library), ama dhig ballaciisa iyo dhererkiisa.','This video is not from the Media Library, so its size is unknown and the page will jump when it loads. Upload it to the Media Library instead.'=>'Muuqaalkani kama iman Maktabadda Warbaahinta, markaa cabbirkiisu lama yaqaan oo boggu wuu boodi doonaa mark uu soo shubmayo. Beddelkeeda, geli Maktabadda Warbaahinta.','An image, video or frame in this HTML has no width and height, so the page will jump when it loads. Add width and height attributes to it.'=>'Muuqaal, fiiyo ama qaab ku jira HTML-kan malaha balac iyo dherer, marka boggu wuu boodayaa marka uu soo go\'ayo. Ku dar sifooyinka balaca iyo dhererka (width and height).','This embed resizes itself after it loads, which moves the content below it. Give it room or place it lower on the page.'=>'Kani wuxuu iskaba beddelaa cabbirka marka uu soo shubo, taas oo dhaqaajisa waxyaabaha hoostiisa ku yaal. Sii boos ama dhig hoose ee bogga.','Layout shift'=>'Isbeddelka qaab-dhismeedka','Heading'=>'Madax','Text'=>'Qoraal','Style'=>'Habka','Plain'=>'Caadi','Accent'=>'Lamaanaha luqadda','No languages to switch between. The switcher appears when a translation plugin lists two or more languages.'=>'Ma jiraan luuqado la isku beddelayo. Beddeluhu wuxuu soo baxayaa marka qalabka turjumaaddu uu liis gareeyo laba ama in ka badan oo luuqadood.','Switcher'=>'Beddeleeyaha','Show the current language'=>'Muuji luqadda hadda taagan','%s is also editing this page. Saving may overwrite their changes.'=>'%s sido kale waa ay/uu wax ka bedelayaa boggan. Keydintu waxayna tirtiri kartaa isbeddelladooda.','Block library'=>'Maktabadda xannibaadda','Layers'=>'Lakabado','Close panel'=>'Xir guddiga','Page canvas'=>'Bogga fanka','Revisions'=>'Dib-u-eegisyada','Block settings'=>'Dejinta xannibaadda','Add block: %s'=>'Kudar baloog: %s','(no title)'=>'(Cinwaan la\'aan)','Open in Studio: %s'=>'Ka fur Studio: %s','Undo'=>'Ka noqo','Redo'=>'Dib u samee','Show or hide layers'=>'Muuji ama qari lakabyada','Show or hide the block library'=>'Muuji ama qari maktabadda baloogga','Show revisions'=>'Muuji dib-u-eegisyada','Open the normal editor'=>'Fur tafatiraha caadiga ah','Keyboard shortcuts'=>'Gaaban-gaabyada kiiboodhka','Preview: desktop'=>'Horay u eeg: desktop-ka','Preview: tablet'=>'Horudhaca: tablet','Preview: mobile'=>'Horay u eeg: moobilka','Copy style of the selected block'=>'Nuqul ka qaado qaabka baloogga la doortay','Paste style onto the selected block'=>'Qaabka ku dheji xannibaadda la doortay','Copy the selected section'=>'Koobi qaybta la xushay','Paste a copied section'=>'Geli qayb la koobiyay','Turn off safe mode'=>'Dam modo amaanka','Turn on safe mode (other plugins off, for you, in Studio only)'=>'Daar habka nabdoon (plugins-ka kale waa dansan yihiin, adiga awgeed, Studio kaliya)','Published'=>'La daabacay','Scheduled'=>'Qorsheysan','Pending review'=>'Waxa la sugayaa dib u eegis','Private'=>'Gaar loo leeyahay','Draft'=>'Qabyo','All changes saved'=>'Dhammaan isbeddellada waa la kaydiyay','Saving…'=>'Kaydinaya…','Autosaving…'=>'Kaydinaya…','Unsaved changes'=>'Isbeddellada aan la kaydin','autosaved'=>'si toos ah loo keydiyey','Desktop preview'=>'Horudhaca desktop-ka','Tablet preview'=>'Horudhaca Kiniinka','Mobile preview'=>'Horudhaca mobaayilka','Studio toolbar'=>'Qalabka Studio','Back to the normal editor'=>'Ku noqo tafatiraha caadiga ah','Page title'=>'Cinwaanka bogga','Preview width'=>'Ballaca horudhaca','Command palette'=>'Baakadaha amarka','View page (opens in a new tab)'=>'Daawado bogga (waxaa lagu furayaa tab cusub)','Update'=>'Cusbooneysii','Save draft'=>'Kaydi qabyada','Publish'=>'Daabac','Restore unsaved changes?'=>'Ma rabtaa inaad soo celiso isbeddellada aan la kaydin?','This page has changes that were never saved. They were kept in this browser:'=>'Boggan wuxuu leeyahay isbeddello aan weligood la keydin. Waxaa lagu hayay biraawsarkan:','This page has a newer autosave than the saved version:'=>'Boggan wuxuu leeyahay keydin cusub oo si otomaatig ah loo sameeyay marka loo eego nooca la keydiyay:','Restore unsaved changes'=>'Soceli isbeddellada aan la keydinin','Discard'=>'Basaal','Revisions could not be loaded.'=>'Dib-u-eegisyada lama soo dejin karo.','Revision restored. Save to keep it, or undo to go back.'=>'Dib-u-eegistii waa la soo celiyay. Kaydi si aad u hayso, ama ka noqo si aad dib ugu noqoto.','Close revisions'=>'Xir wax-ka-beddellada','No revisions yet. Each save makes one.'=>'Weli wax dib u eegis ah ma jiraan. Kaydin kastaa waxay samaysaa mid.','Revision from %s'=>'Dib-u-eegistii laga bilaabo %s','Restore this revision'=>'Soceli dib u eegistan','Cancel'=>'Jooji','Safe mode could not be changed.'=>'Habka badbaadada lama beddeli karin.','Safe mode is on.'=>'Habka badbaadada waa shidhan yahay.','%d other plugin is switched off, for you and in Sandwich Studio only. The live site and other users are not affected.'=>'%dplugin kale ayaa dansan, adiga iyo Sandwich Studio keliya. Bogga tooska ah iyo isticmaaleyaasha kale ma saameyn doono.' . "\0" . '%d plugins kale waa la damiyay, adiga iyo Sandwich Studio keliya. Bogga tooska ah iyo isticmaaleyaasha kale ma saameynayo.','Safe mode: switch other plugins off in Studio, for you only'=>'Habka nabdoon: dami furayaasha kale ee Studio, adiga keligaa','Safe mode'=>'Habka badbaadada','Save your changes.'=>'Keydi isbeddelladaada.','Undo your last change.'=>'Ka noqo isbeddelkaagii ugu dambeeyay.','Redo your last undo.'=>'Ku celi wixii aad ugu dambaysay ee aad dib u celisay.','Show or hide the layers panel.'=>'Muuji ama qari guddiga lakabyada.','Display these keyboard shortcuts.'=>'Muuji gaaban-yada kiiboodhkan.','Select a block first.'=>'Markuu hore u dooro baloog.','Style copied. Paste it onto any block, on this site or another.'=>'Qaabka waa la guuriyay. Ku dheji baloog kasta, boggan ama mid kale.','The browser refused to copy.'=>'Barawarku wuu diiday inuu guuriyo.','Section copied. Paste it into any page, on this site or another.'=>'Qeybta waa la koobiyay. Ku dhaji bog kasta, oo ku yaal boggan ama mid kale.','The clipboard does not hold a style copied from Sandwich Studio.'=>'Sabxadda goyntu ma hayso qaab laga soo guuriyay Sandwich Studio.','Style pasted onto %d block.'=>'Qaabka lagu dhejiyay %d baloog.' . "\0" . 'Qaabka waxaa lagu dhejiyay %d baloog.','That style does not fit the selected block.'=>'Habkaas kuma habboona xannibaadda la xulay.','The clipboard does not hold a copied section.'=>'Looxa qoraalka ayaa wada haynin qayb la koobiyay.','Section pasted.'=>'Qaybta la keenay.','Paste style'=>'Ku dhaji qaabka','Paste section'=>'Qeybta dhaji','Press Ctrl+V (or Cmd+V on a Mac) here to paste'=>'Riix Ctrl+V (ama Cmd+V oo ku taal Mac) halkan si aad u dhajiso','Copy style'=>'Nuqulka qaabka','Copy section'=>'Nuqul ka qaado qaybta','Edit in Sandwich Studio'=>'Ku Tasi Sandwich Studio','Saving failed. Check your connection and try again; your changes are kept in this browser.'=>'Kaydintu waa guuldarraystay. Hubi xidhiidhkaaga oo dib isku day; isbeddeladaadu waxay ku jiraan biraawsarkan.','Published.'=>'La daabacay.','Saved.'=>'La kaydiyay.','block titleButton link'=>'Isku xirka badhanka','block descriptionA link styled as a button.'=>'Isku xirka loo qaabeeyey sidii badhan oo kale.','block keywordbutton'=>'badhanka','block keywordlink'=>'ku xir','block keywordcall to action'=>'ficirka ficilka','block titleColumn'=>'Tiirka','block descriptionA column inside a row. It can hold any block.'=>'Safka gudihiisa ku jira tiir. Wuxuu xambaari karaa baloog kasta.','block keywordcolumn'=>'safka','block keywordlayout'=>'Qaab-dhismeedka','block titleLanguage switcher (sample)'=>'Badalka luqadda (muunad)','block descriptionLists the site\'s languages from the translation plugin, when one is active. It renders nothing otherwise.'=>'Wuxuu soo bandhigayaa luqadaha mareegaha ee laga helayo qalabka turjumaadda, marka uu mid ka mid ahi shaqeeyo. Haddii kale waxba ma soo bandhigayo.','block keywordlanguage'=>'Luqad','block keywordswitcher'=>'kala beddelaha','block titleSample content'=>'Nuxurka tusaalaha','block descriptionA heading and a paragraph, rendered with neutral class names. It is the reference block for the translation contract.'=>'Cinwaan iyo baaragaraaf, oo lagu soo bandhigay magacyo fasal oo caadi ah. Waa blogga tixraaca ee heshiiska tarjumaadda.','block keywordsample'=>'muunad','block keywordtext'=>'qoraal','block titleIcon'=>'Astaamaha','block descriptionAn SVG icon. The markup is cleaned before it is shown.'=>'Calaamad SVG ah. Qoraalka calaamadaynta waxaa la nadiifiyaa ka hor intaan la soo bandhigin.','block keywordicon'=>'Astaanta','block keywordsvg'=>'svg','block titleRow'=>'Saf','block descriptionA row of columns. Stays readable if the plugin is ever turned off.'=>'Safafka tiirarka ah. Wuxuu ahaadaa mid la akhrin karo haddii qalabka dheeriga ah la damiyo.','block keywordrow'=>'safaf','block keywordcolumns'=>'tiirarka','block titleShortcode (add-on)'=>'Gaabiyaha (ku-dar)','block descriptionA shortcode from an add-on written for the classic Page Builder Sandwich editor, with the settings the add-on declared.'=>'Gaabane (shortcode) oo ka yimid lifaaq loogu talagalay tafatiraha classic Page Builder Sandwich, oo wata dejinta uu lifaaqu caddeeyay.','block keywordshortcode'=>'shortcode','block keywordadd-on'=>'dheeraad ah','block titleWidget area'=>'Goobta wiijiga','block descriptionShows the widgets in one of the theme\'s widget areas.'=>'Wuxuu muujinayaa widget-yada mid ka mid ah meelaha widget-ka ee mawduuca.','block keywordsidebar'=>'garabka dhinaca','block keywordwidget area'=>'agagaarka widget-ka','block titleWidget'=>'Widget','block descriptionShows one of the site\'s registered classic widgets.'=>'Waxay soo bandhigaysaa mid ka mid ah agabka kala duwan ee classic-ga ah ee barta diiwaangashan.','block keywordwidget'=>'qalabka yaryar']];